/**
 * Task Queue with Retry Backoff, Cancellation, Concurrency Limits
 * 
 * Design Decisions:
 * 1. We use a generic Task type to allow any async function as a task.
 * 2. Each task has metadata including retry count, max retries, and backoff strategy.
 * 3. The queue manages concurrency by tracking active tasks and queuing pending ones.
 * 4. Cancellation is handled via AbortController per task, allowing graceful cancellation.
 * 5. Exponential backoff with jitter prevents thundering herd problems on retries.
 * 6. Tasks are processed in FIFO order but can be prioritized if needed (not implemented here).
 * 7. Error handling distinguishes between cancellations and actual errors.
 * 8. The queue emits events for monitoring purposes (start, complete, error, cancel).
 */

// ==================== Types ====================

type TaskStatus = 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';

interface TaskMetadata {
  id: string;
  status: TaskStatus;
  createdAt: number;
  startedAt?: number;
  completedAt?: number;
  retryCount: number;
  maxRetries: number;
  lastError?: Error;
}

interface TaskResult<T> {
  taskId: string;
  success: boolean;
  data?: T;
  error?: Error;
  duration: number;
  attempts: number;
}

interface TaskOptions {
  maxRetries?: number;
  backoffBaseMs?: number;
  backoffMaxMs?: number;
  timeoutMs?: number;
  priority?: number; // Higher priority runs first among same-status tasks
}

interface Queued

